css:
[data-bz-node="s5h1"][data-bz-node] h2{font-family:Oswald, sans-serif;font-size:clamp(28px, 4vw, 42px);font-weight:700;font-style:normal;line-height:1.1;letter-spacing:normal;text-transform:uppercase;text-align:start;color:rgb(255, 255, 255);margin-top:0px;margin-right:0px;margin-bottom:32px;margin-left:0px}
[data-bz-node="s5r2"][data-bz-node]{grid-template-columns:repeat(auto-fit, minmax(280px, 1fr))}
[data-bz-node^="s5h4-r"][data-bz-node] h3{font-family:Oswald, sans-serif;font-size:clamp(22px, 2.4vw, 28px);font-weight:700;font-style:normal;line-height:1.15;letter-spacing:0.04em;text-transform:uppercase;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s5t5-r"][data-bz-node] p{font-family:Oswald, sans-serif;font-size:22px;font-weight:600;font-style:normal;line-height:normal;letter-spacing:0.04em;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s5t5-r"][data-bz-node] a:nth-of-type(1){color:rgb(20, 21, 26);text-decoration:none}
[data-bz-node^="s5t5-r"][data-bz-node] a:nth-of-type(1):hover{color: rgb(196, 18, 48)}
[data-bz-node^="s5t5-r"][data-bz-node] a:nth-of-type(1):focus{outline: rgb(196, 18, 48) solid 3px; outline-offset: 2px}
[data-bz-node^="s5b6-r"][data-bz-node] .bz-btn{margin:0;line-height:normal;background:transparent;border:0;border-radius:0;box-shadow:none;padding:0;display:inline-block;color:#C41230;text-decoration:underline;align-self:flex-start;margin-top:auto;background:rgb(196, 18, 48);color:rgb(255, 255, 255);text-decoration:none;font-weight:600;font-size:15px;font-family:Oswald, sans-serif;letter-spacing:0.1em;text-transform:uppercase;padding-top:16px;padding-right:28px;padding-bottom:16px;padding-left:28px}
[data-bz-node^="s5b6-r"][data-bz-node] .bz-btn:hover{background: rgb(143, 13, 33); color: rgb(255, 255, 255)}
[data-bz-node^="s5b6-r"][data-bz-node] .bz-btn:focus{outline: rgb(20, 21, 26) solid 3px; outline-offset: 3px}
[data-bz-node^="s5b6-r"][data-bz-node] .bz-btns{margin:0;gap:0}
[data-bz-node="s5"][data-bz-node]{padding-top:clamp(56px, 8vw, 100px);padding-bottom:clamp(56px, 8vw, 100px)}
